struct vector3d
{
  float x;
  float y;
  float z;
};

struct KSEntityPO
{
  vector3d KSPos;
  char padding[0x44];
};

class KSReplay
{
  char padding0[0x34];
public:
  unsigned int playframe;
private:
  char padding1[0x1c];
  unsigned int numFrames;
  char padding2[0x14];
  KSEntityPO *mainEntityPO;
public:
  void MainEntityPos(vector3d &pos, int frame = -1);
};

extern KSReplay ksreplay;
__asm__(".equ ksreplay, 0x004252A8");

const unsigned int MAINENTITY_UPDATEFRAMES = 4;

void KSReplay::MainEntityPos(vector3d &pos, int f)
{
  if(f == -1)
    f = ksreplay.playframe;

  if(f >= numFrames)
    f = numFrames-1;

  int poframe = f/MAINENTITY_UPDATEFRAMES;
  int interpframe = f%MAINENTITY_UPDATEFRAMES;

  if(interpframe == 0 || f == numFrames-1)
    pos = mainEntityPO[poframe].KSPos;
  else
  {
    float interp = (float)interpframe/(float)MAINENTITY_UPDATEFRAMES;
    pos.x = (1.0f-interp)*mainEntityPO[poframe].KSPos.x + interp*mainEntityPO[poframe+1].KSPos.x;
    pos.y = (1.0f-interp)*mainEntityPO[poframe].KSPos.y + interp*mainEntityPO[poframe+1].KSPos.y;
    pos.z = (1.0f-interp)*mainEntityPO[poframe].KSPos.z + interp*mainEntityPO[poframe+1].KSPos.z;
  }
}
